use ao_reason_workbench::{config::{Actor,NodeSpec},core::{store::Store,protocol::{Envelope,PROTOCOL},controller::ControlService}};
use serde_json::json;
fn node()->NodeSpec{NodeSpec{id:"B".into(),address:"local-B/runner".into(),key_hex:"07".repeat(32),slots:1,admitted:true,healthy:true,draining:false,templates:vec!["sum-native-v1".into(),"control-native-v1".into()]}}
fn event(r:&ao_reason_workbench::core::store::Run,kind:&str,payload:serde_json::Value)->Envelope{let mut e=Envelope{schema:PROTOCOL.into(),message_id:uuid::Uuid::new_v4().to_string(),deployment:"native".into(),from:"B".into(),to:"A".into(),run_id:r.id.clone(),attempt:r.attempt,epoch:r.epoch.clone(),kind:kind.into(),sent_at:100,expires_at:400,payload,mac:String::new()};e.sign(&[7;32]).unwrap();e}
#[test]
fn seven_tools_bind_owner_and_reject_extra_arguments(){let t=tempfile::tempdir().unwrap();let store=Store::open(&t.path().join("c.db"),"native",&[node()]).unwrap();let actor=Actor::Local("me".into());let mut c=ControlService::new(store,actor.clone());assert!(c.call("dispatch",json!({"template":"sum-native-v1","owner":"forged"}),100).is_err());let r=c.call("dispatch",json!({"template":"sum-native-v1"}),100).unwrap();let id=r["id"].as_str().unwrap();assert!(c.call("status",json!({"run_id":id}),100).is_ok());let store=Store::open(&t.path().join("c.db"),"native",&[node()]).unwrap();let mut other=ControlService::new(store,Actor::AoSession("me".into()));assert!(other.call("status",json!({"run_id":id}),100).is_err());assert!(c.call("shell",json!({}),100).is_err());assert_eq!(ControlService::tool_names().len(),7);}
#[test]
fn inbox_duplicate_is_persisted_and_late_report_cannot_overwrite_cancel(){let t=tempfile::tempdir().unwrap();let mut s=Store::open(&t.path().join("c.db"),"native",&[node()]).unwrap();let actor=Actor::Local("me".into());let r=s.dispatch(&actor,"sum-native-v1",100).unwrap();s.assign_next(100).unwrap();let started=event(&r,"status",json!({"state":"running","session":"worker-1","spawn_intent":true}));assert!(s.receive(&started,110).unwrap());assert!(!s.receive(&started,110).unwrap());s.cancel(&actor,&r.id).unwrap();let done=event(&r,"report",json!({"session":"worker-1","report":{"sum":6},"verification":{"passed":true,"source":"native-verifier"}}));s.receive(&done,110).unwrap();assert_eq!(s.run(&r.id).unwrap().status,"cancel_pending");assert!(!s.assignment(&r.id,1).unwrap().unwrap().released);drop(s);let mut s=Store::open(&t.path().join("c.db"),"native",&[node()]).unwrap();assert!(!s.receive(&started,110).unwrap());}
#[test]
fn approval_scope_and_decision_are_exact_and_durable(){let t=tempfile::tempdir().unwrap();let mut s=Store::open(&t.path().join("c.db"),"native",&[node()]).unwrap();let actor=Actor::Local("me".into());let r=s.dispatch(&actor,"control-native-v1",100).unwrap();s.assign_next(100).unwrap();s.receive(&event(&r,"status",json!({"state":"running","session":"worker-1","spawn_intent":true})),110).unwrap();let approval=json!({"session":"worker-1","request_id":"req-1","generation":1,"scope_hash":"abc","expires_at":300,"offered":["allow_once","reject_once"],"summary":"模拟一次性授权"});s.receive(&event(&r,"approval",approval),110).unwrap();assert_eq!(s.approvals(&actor,&r.id,110).unwrap().len(),1);let mut c=ControlService::new(s,actor);let mut args=json!({"run_id":r.id,"request_id":"req-1","generation":1,"scope_hash":"wrong","decision_id":"allow_once"});assert!(c.call("decide",args.clone(),110).is_err());args["scope_hash"]=json!("abc");let result=c.call("decide",args.clone(),110).unwrap();assert_eq!(result["state"],"queued");assert!(c.call("decide",args,110).is_err());assert!(c.store.approvals(&Actor::Local("me".into()),&r.id,110).unwrap().is_empty());assert_eq!(c.store.outbox_count().unwrap(),2);}
#[test]
fn inbound_wrong_node_or_stale_execution_cannot_release(){let t=tempfile::tempdir().unwrap();let mut s=Store::open(&t.path().join("c.db"),"native",&[node()]).unwrap();let r=s.dispatch(&Actor::Local("me".into()),"sum-native-v1",100).unwrap();s.assign_next(100).unwrap();let mut e=event(&r,"status",json!({"state":"unknown","reason":"lost create response","spawn_intent":true}));e.from="C".into();e.sign(&[7;32]).unwrap();assert!(s.receive(&e,110).is_err());e.from="B".into();e.attempt=2;e.sign(&[7;32]).unwrap();assert!(s.receive(&e,110).is_err());assert_eq!(s.run(&r.id).unwrap().status,"accepted");}
